'use strict';
window.factoryLearning=api=>{
 const {items,recipes,esc}=api,$=s=>document.querySelector(s),fmt=n=>Number(n.toFixed(2)).toString();
 const recipeFor=item=>Object.entries(recipes).find(([,r])=>r.output===item);
 const dockValues=()=>api.get().deliveries.slice(0,api.get().level.secondDock?2:1);
 const goals=()=>api.get().level.rateGoals||Array(api.get().level.secondDock?2:1).fill(api.get().level.rate);
 function requirements(target){const rates={};function visit(item,rate){rates[item]=(rates[item]||0)+rate;const found=recipeFor(item);if(found)for(const [input,n]of Object.entries(found[1].input))visit(input,rate*n);}visit(api.get().level.target,target);return Object.entries(rates).map(([item,rate])=>{const found=recipeFor(item),cells=[...api.get().cells.values()],capacity=found?cells.filter(c=>c.type===found[0]).reduce((n)=>n+api.recipeRate(found[1]),0):cells.filter(c=>c.type==='extractor'&&api.sourceAt(c.x,c.y)?.[0]===item).reduce((n,c)=>n+api.sourceAt(c.x,c.y)[3],0),unit=found?api.recipeRate(found[1]):null;const terms=Object.values(recipes).filter(r=>r.input[item]&&rates[r.output]).map(r=>`${fmt(rates[r.output])} × ${r.input[item]}`),formula=terms.length?terms.join(' + ')+` = ${fmt(rate)}`:`Target = ${fmt(rate)}`;return {item,rate,formula,capacity,unit,machines:unit?Math.ceil(rate/unit):null};});}
 function rate(c){const s=api.get(),window=30;return window>0?(c.flow||[]).filter(f=>f.time>s.time-30).length*60/window:0;}
 function capacity(c){return recipes[c.type]?api.recipeRate(recipes[c.type]):c.type==='extractor'?api.sourceAt(c.x,c.y)?.[3]||0:api.isTransport(c)?api.beltRate():null;}
 function evidence(){const s=api.get();return [...s.cells.values()].filter(c=>c.type!=='dock').map(c=>({type:c.type,x:c.x,y:c.y,rate:rate(c),capacity:capacity(c),blocked:(c.blockedFor||0)>=2,status:c.status}));}
 function graph(){const s=api.get(),samples=s.timeline||[],max=Math.max(1,...goals(),...samples.flatMap(p=>p.rates)),start=Math.max(0,s.time-120),end=Math.max(start+1,s.time),x=t=>50+500*(t-start)/(end-start),y=r=>162-130*r/max,colors=['#227d60','#c58724'];return `<figure class="rate-graph"><svg viewBox="0 0 590 205" role="img" aria-label="Delivery rate graph. Horizontal axis simulation seconds, vertical axis items per minute."><text x="12" y="16">items/min</text>${[0,.5,1].map(f=>`<path d="M50 ${y(max*f)}H550" stroke="#d4e5d4"/><text x="42" y="${y(max*f)+4}" text-anchor="end">${fmt(max*f)}</text>`).join('')}${goals().map((g,i)=>`<path d="M50 ${y(g)}H550" stroke="${colors[i]}" stroke-dasharray="5 5" opacity=".5"/>`).join('')}${dockValues().map((_,i)=>`<polyline fill="none" stroke="${colors[i]}" stroke-width="3" points="${samples.filter(p=>p.time>=start).map(p=>`${x(p.time)},${y(p.rates[i]||0)}`).join(' ')}"/>`).join('')}<text x="50" y="185">${Math.floor(start)}s</text><text x="550" y="185" text-anchor="end">${Math.floor(end)}s</text><text x="300" y="200" text-anchor="middle">Simulation time</text></svg><figcaption>${dockValues().map((_,i)=>`<span style="color:${colors[i]}">● Dock ${i+1}</span>`).join(' · ')} · dashed lines: goals. Rolling 30-second rates; first 30 seconds warm up.</figcaption></figure>`;}
 const tabs=active=>`<div class="math-tabs"><button data-math-plan aria-pressed="${active==='plan'}">Production planner</button><button data-math-review aria-pressed="${active==='review'}">Review the run</button></div>`;
 const pad=()=>`<div class="math-keypad" aria-label="Touch number pad">${['1','2','3','4','5','6','7','8','9','.','0','⌫'].map(k=>`<button data-math-key="${k}">${k}</button>`).join('')}</div>`;
 function capturePlan(){const s=api.get(),target=Number($('#plan-target')?.value);if(!Number.isFinite(target)||target<=0||target>240){$('#plan-feedback').textContent='Choose a target above 0 and at most 240 items/min.';return false;}s.plan={...s.plan,target,guesses:Object.fromEntries([...document.querySelectorAll('[data-estimate]')].map(el=>[el.dataset.estimate,el.value.slice(0,10)]))};api.save();return true;}
 function planner(){const s=api.get(),target=s.plan?.target||goals().reduce((a,b)=>a+b,0),rows=requirements(target),revealed=s.plan?.revealed;api.open(`${api.heading('CALCULATE · BUILD · COMPARE','Math lab')}${tabs('plan')}<p>Choose your <b>total output across all docks</b>. Calculate each ingredient rate before revealing the recipe calculations.</p><label class="plan-target" for="plan-target">Target ${items[s.level.target][0].toLowerCase()} / minute <input id="plan-target" inputmode="decimal" value="${target}" maxlength="10" data-math-number></label><button data-plan-target>Update target</button><div class="math-table-wrap"><table class="math-table"><thead><tr><th>Item</th><th>Your rate / min</th><th>Recipe calculation</th><th>Machines needed</th><th>Built capacity / min</th></tr></thead><tbody>${rows.map(row=>`<tr><th><label for="estimate-${row.item}">${items[row.item][0]}</label></th><td><input id="estimate-${row.item}" data-estimate="${row.item}" data-math-number inputmode="decimal" maxlength="10" value="${esc(s.plan?.guesses?.[row.item]||'')}" aria-label="Predicted ${items[row.item][0]} per minute"></td><td>${revealed?`${row.formula} / min`:'Calculate first'}</td><td>${revealed?(row.unit?`${fmt(row.rate)} ÷ ${fmt(row.unit)} → <b>${row.machines}</b>`:'Resource supply'):'—'}</td><td data-plan-capacity="${row.item}"></td></tr>`).join('')}</tbody></table></div>${pad()}<div class="math-actions"><button class="primary" data-plan-check>Check calculations</button><button data-plan-save>Save my plan</button><button data-plan-hide>Hide calculations</button></div><p id="plan-feedback" role="status">${revealed?'Required rates come from multiplying each recipe ingredient by the output target. Machine counts round up.':''}</p><div id="planner-live"></div><p class="small-note">Built capacity is the theoretical total of placed machines, not a promise of output. Connected supply, routing and congestion matter. Active motor upgrades are included; extractors stay unchanged.</p>`,true);update();bindNumberPad();}
 function update(){if(!$('#planner-live'))return;const s=api.get(),rows=requirements(s.plan?.target||goals().reduce((a,b)=>a+b,0)),actual=dockValues().map((_,i)=>dockRate(i));$('#planner-live').innerHTML=`<div class="feedback">Planned total: <b>${fmt(s.plan?.target||goals().reduce((a,b)=>a+b,0))} / min</b> · Actual delivered: <b>${fmt(actual.reduce((a,b)=>a+b,0))} / min</b>${s.time<30?' · Warming up':''}</div>`;for(const row of rows){const el=$(`[data-plan-capacity="${row.item}"]`);if(el){el.textContent=fmt(row.capacity);el.className=row.capacity+1e-8<row.rate?'capacity-low':'capacity-ready';el.title=row.capacity<row.rate?'Capacity below your target':'Enough theoretical capacity';}}}
 function dockRate(i){const s=api.get(),window=30;return window>0?(s.deliveryFlow||[]).filter(h=>h.dock===i&&h.time>s.time-30).length*60/window:0;}
 function review(){const s=api.get(),rows=evidence(),blocked=rows.filter(r=>r.blocked),starved=rows.filter(r=>recipes[r.type]&&r.status.startsWith('Waiting')),target=s.plan?.target||goals().reduce((a,b)=>a+b,0);api.open(`${api.heading('MEASURE · EXPLAIN · IMPROVE','Review your factory')}${tabs('review')}<div class="math-summary"><div>Planned total<strong>${fmt(target)} / min</strong></div><div>Actual total<strong>${fmt(dockValues().map((_,i)=>dockRate(i)).reduce((a,b)=>a+b,0))} / min</strong></div><div>Construction<strong>${s.level.budget-s.budget} credits</strong></div></div>${graph()}<div class="feedback"><b>Evidence from this run</b><p>${blocked.length?`${blocked.length} pieces have waited at least 2 seconds for their output to clear.`:'No output has been blocked continuously for 2 seconds.'} ${starved.length?`${starved.length} factories are waiting for ingredients.`:''}</p><p>Check the flow overlay and the input rates in your planner. A blocked belt can be a symptom of a machine farther downstream.</p></div><div class="math-table-wrap"><table class="math-table"><thead><tr><th>Piece</th><th>Actual output / min</th><th>Rated capacity / min</th><th>Observed status</th></tr></thead><tbody>${rows.filter(r=>recipes[r.type]||r.type==='extractor'||r.blocked).map(r=>`<tr><td>${esc(recipes[r.type]?.name||r.type)} (${r.x+1}, ${r.y+1})</td><td>${fmt(r.rate)}</td><td>${fmt(r.capacity||0)}</td><td>${esc(r.status)}</td></tr>`).join('')}</tbody></table></div><label class="reflection-label" for="math-explanation">Which machine or connection limited output? Show a calculation using its rate and the recipe.</label><textarea id="math-explanation" rows="3" maxlength="1600">${esc(s.reflection?.explanation||'')}</textarea><label class="reflection-label" for="math-improvement">What will you change, and what output do you predict afterward?</label><textarea id="math-improvement" rows="2" maxlength="1000">${esc(s.reflection?.improvement||'')}</textarea><div class="math-actions"><button class="primary" data-reflection-save>Save team explanation</button><button data-review-refresh>Refresh evidence</button><button data-close>Test our improvement</button></div><p id="review-feedback" role="status"></p><p class="small-note">Your explanation is saved for this team and level. Discuss it with your teacher; it is not automatically graded.</p>`,true);}
 function saveReflection(){const s=api.get();s.reflection={explanation:$('#math-explanation')?.value.slice(0,1600)||'',improvement:$('#math-improvement')?.value.slice(0,1000)||'',time:s.time};api.save();}
 let activeNumber=null;
 function bindNumberPad(){activeNumber=$('#plan-target');document.querySelectorAll('[data-math-number]').forEach(el=>{el.onfocus=()=>{activeNumber=el;};});}
 $('#modal').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-math-plan'))planner();if(b.hasAttribute('data-math-review'))review();if(b.hasAttribute('data-plan-target')&&capturePlan()){api.get().plan.revealed=false;api.save();planner();}if(b.hasAttribute('data-plan-save')&&capturePlan())$('#plan-feedback').textContent='Plan saved for your team and this level.';if(b.hasAttribute('data-plan-hide')&&capturePlan()){api.get().plan.revealed=false;api.save();planner();}if(b.hasAttribute('data-plan-check')&&capturePlan()){const s=api.get(),rows=requirements(s.plan.target),correct=rows.filter(r=>s.plan.guesses[r.item]!==''&&Number.isFinite(Number(s.plan.guesses[r.item]))&&Math.abs(Number(s.plan.guesses[r.item])-r.rate)<.01).length;s.plan.revealed=true;api.save();planner();$('#plan-feedback').textContent=`${correct} of ${rows.length} rates match. Follow the recipe multipliers and compare the calculated rates above.`;}if(b.dataset.mathKey&&activeNumber?.isConnected){const k=b.dataset.mathKey,value=activeNumber.value,start=activeNumber.selectionStart??value.length,end=activeNumber.selectionEnd??start,left=k==='⌫'&&start===end?Math.max(0,start-1):start,insert=k==='⌫'?'':k,result=value.slice(0,left)+insert+value.slice(end);if(result.length<=10&&(result.match(/\./g)||[]).length<=1){activeNumber.value=result;activeNumber.focus();activeNumber.setSelectionRange(left+insert.length,left+insert.length);}}if(b.hasAttribute('data-reflection-save')){saveReflection();$('#review-feedback').textContent='Team explanation saved.';}if(b.hasAttribute('data-review-refresh')){saveReflection();review();}});
 function snapshot(){return {plan:api.get().plan,reflection:api.get().reflection,requirements:requirements(api.get().plan?.target||goals().reduce((a,b)=>a+b,0)),flows:evidence(),timeline:api.get().timeline};}
 return {planner,review,update,rate,capacity,snapshot,dockRate};
};
